"use client";

import { useEffect, useMemo, useState } from "react";
import { AlertCircle, CheckCircle2, Database, Download, FileUp, Play, Plus, Save, Trash2, Wand2 } from "lucide-react";
import { parseByRule, validateRows } from "@/lib/rule-engine";
import type { OrderField, OrderRow, ParseRule, SheetSnapshot, ValidationIssue } from "@/lib/types";

const fields: { key: OrderField; label: string }[] = [
  { key: "externalCode", label: "外部编码" },
  { key: "storeName", label: "收货门店" },
  { key: "receiverName", label: "收件人" },
  { key: "receiverPhone", label: "电话" },
  { key: "receiverAddress", label: "地址" },
  { key: "skuCode", label: "SKU编码" },
  { key: "skuName", label: "SKU名称" },
  { key: "quantity", label: "数量" },
  { key: "spec", label: "规格" },
  { key: "remark", label: "备注" }
];

const seedRules: ParseRule[] = [
  {
    id: "table-hunan",
    name: "标准明细表：表头映射 + 单号聚合",
    mode: "table",
    sheetStrategy: "first",
    headerRow: 2,
    dataStartRow: 3,
    mappings: {
      externalCode: { source: "header", header: "配送单号" },
      storeName: { source: "header", header: "收货机构" },
      receiverName: { source: "header", header: "收货人" },
      receiverPhone: { source: "header", header: "联系电话" },
      receiverAddress: { source: "header", header: "收货地址" },
      skuCode: { source: "header", header: "物品编码*" },
      skuName: { source: "header", header: "物品名称" },
      quantity: { source: "header", header: "应发数量" },
      spec: { source: "header", header: "规格型号" },
      remark: { source: "header", header: "备注" }
    }
  },
  {
    id: "tail-info",
    name: "尾部收货信息：跳过头部 + 底部提取",
    mode: "table",
    sheetStrategy: "first",
    headerRow: 4,
    dataStartRow: 5,
    stopWhenContains: "合计",
    mappings: {
      skuCode: { source: "index", index: 3 },
      skuName: { source: "index", index: 4 },
      quantity: { source: "index", index: 12 },
      spec: { source: "index", index: 6 }
    },
    tailExtractions: [
      { field: "receiverName", label: "收货人" },
      { field: "receiverPhone", label: "电话" },
      { field: "receiverAddress", label: "地址" },
      { field: "storeName", label: "收货机构" }
    ]
  },
  {
    id: "multi-sheet",
    name: "多 Sheet 同构出库单",
    mode: "table",
    sheetStrategy: "all",
    headerRow: 4,
    dataStartRow: 5,
    stopWhenContains: "合计",
    mappings: {
      storeName: { source: "sheet" },
      skuCode: { source: "header", header: "物品编码" },
      skuName: { source: "header", header: "物品名称" },
      spec: { source: "header", header: "规格型号" },
      quantity: { source: "header", header: "出库数量" },
      remark: { source: "header", header: "备注" }
    },
    tailExtractions: [
      { field: "receiverName", label: "收货人" },
      { field: "receiverPhone", label: "电话" },
      { field: "receiverAddress", label: "地址" }
    ]
  },
  {
    id: "cards",
    name: "卡片式调拨单：边界 + 内部小表",
    mode: "cards",
    sheetStrategy: "first",
    boundaryPattern: "调拨记录",
    itemHeaderPattern: "物品编码",
    mappings: {
      skuCode: { source: "header", header: "物品编码" },
      skuName: { source: "header", header: "物品名称" },
      spec: { source: "header", header: "规格型号" },
      quantity: { source: "header", header: "数量" },
      remark: { source: "header", header: "备注" }
    },
    tailExtractions: [
      { field: "storeName", label: "调入门店" },
      { field: "receiverName", label: "收货人" },
      { field: "receiverPhone", label: "电话" },
      { field: "receiverAddress", label: "收货地址" }
    ]
  },
  {
    id: "matrix-store",
    name: "门店矩阵：SKU × 门店转置",
    mode: "matrix",
    sheetStrategy: "first",
    headerRow: 1,
    dataStartRow: 2,
    matrixValueStartColumn: 14,
    matrixValueEndColumn: 16,
    mappings: {
      skuName: { source: "index", index: 3 },
      skuCode: { source: "index", index: 5 },
      spec: { source: "index", index: 8 },
      remark: { source: "index", index: 2 }
    }
  }
];

const sheetRowsFromText = (name: string, content: string): SheetSnapshot[] => [{
  name,
  rows: content.split(/\r?\n/).map((line) => [line])
}];

const excelCellText = (value: unknown): string => {
  if (value == null) return "";
  if (typeof value === "object") {
    const record = value as { text?: string; result?: unknown; richText?: { text: string }[] };
    if (record.text) return record.text;
    if (record.result != null) return String(record.result);
    if (record.richText) return record.richText.map((item) => item.text).join("");
  }
  return String(value);
};

export default function Page() {
  const [rules, setRules] = useState<ParseRule[]>(seedRules);
  const [selectedRuleId, setSelectedRuleId] = useState(seedRules[0].id);
  const [ruleText, setRuleText] = useState(JSON.stringify(seedRules[0], null, 2));
  const [sheets, setSheets] = useState<SheetSnapshot[]>([]);
  const [fileName, setFileName] = useState("");
  const [rows, setRows] = useState<OrderRow[]>([]);
  const [history, setHistory] = useState<OrderRow[]>([]);
  const [issues, setIssues] = useState<ValidationIssue[]>([]);
  const [toast, setToast] = useState("等待上传文件");
  const [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState(0);
  const [filter, setFilter] = useState("");
  const selectedRule = rules.find((rule) => rule.id === selectedRuleId) ?? rules[0];
  const existingCodes = useMemo(() => new Set(history.map((row) => row.externalCode).filter(Boolean)), [history]);
  const visibleRows = rows.slice(0, 300);
  const filteredHistory = history.filter((row) => [row.externalCode, row.receiverName, row.storeName].join(" ").includes(filter));

  useEffect(() => {
    const localRules = localStorage.getItem("rules");
    const localHistory = localStorage.getItem("orders");
    if (localRules) setRules(JSON.parse(localRules));
    if (localHistory) setHistory(JSON.parse(localHistory));
    fetch("/api/orders").then((res) => res.json()).then((data) => {
      if (Array.isArray(data.rows) && data.rows.length) setHistory(data.rows);
    }).catch(() => undefined);
  }, []);

  useEffect(() => {
    if (selectedRule) setRuleText(JSON.stringify(selectedRule, null, 2));
  }, [selectedRuleId]);

  const setTimedToast = (message: string): void => setToast(message);

  const readFile = async (file: File): Promise<void> => {
    setBusy(true);
    setProgress(12);
    setFileName(file.name);
    try {
      const buffer = await file.arrayBuffer();
      const lower = file.name.toLowerCase();
      if (lower.endsWith(".xlsx") || lower.endsWith(".xls")) {
        if (lower.endsWith(".xls")) throw new Error(".xls 二进制格式请先另存为 .xlsx 后导入");
        const ExcelJS = await import("exceljs");
        const workbook = new ExcelJS.Workbook();
        await workbook.xlsx.load(buffer);
        const nextSheets = workbook.worksheets.map((sheet) => {
          const rows: string[][] = [];
          sheet.eachRow({ includeEmpty: true }, (row, rowNumber) => {
            rows[rowNumber - 1] = [];
            row.eachCell({ includeEmpty: true }, (cell, columnNumber) => {
              rows[rowNumber - 1][columnNumber - 1] = excelCellText(cell.value);
            });
          });
          return { name: sheet.name, rows };
        });
        setSheets(nextSheets);
      } else if (lower.endsWith(".docx")) {
        const mammoth = await import("mammoth/mammoth.browser");
        const result = await mammoth.extractRawText({ arrayBuffer: buffer });
        setSheets(sheetRowsFromText(file.name, result.value));
      } else if (lower.endsWith(".pdf")) {
        const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
        const doc = await pdfjs.getDocument({ data: new Uint8Array(buffer), disableWorker: true }).promise;
        const lines: string[] = [];
        for (let pageNo = 1; pageNo <= doc.numPages; pageNo += 1) {
          const page = await doc.getPage(pageNo);
          const content = await page.getTextContent();
          lines.push(content.items.map((item: { str?: string }) => item.str ?? "").join(" "));
        }
        setSheets(sheetRowsFromText(file.name, lines.join("\n")));
      } else {
        throw new Error("仅支持 .xlsx/.xls/.docx/.pdf 文件");
      }
      setProgress(100);
      setTimedToast("文件已读取，可选择规则或生成 AI 草案");
    } catch (error) {
      setTimedToast(error instanceof Error ? error.message : "文件读取失败");
    } finally {
      setBusy(false);
    }
  };

  const generateRule = async (): Promise<void> => {
    if (!sheets.length) return setTimedToast("请先上传文件");
    setBusy(true);
    setProgress(35);
    const response = await fetch("/api/ai-rules", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ fileName, sheets: sheets.map((sheet) => ({ ...sheet, rows: sheet.rows.slice(0, 30) })) })
    });
    const data = await response.json();
    const rule = data.rule as ParseRule;
    const nextRules = [rule, ...rules];
    setRules(nextRules);
    setSelectedRuleId(rule.id);
    localStorage.setItem("rules", JSON.stringify(nextRules));
    setProgress(100);
    setBusy(false);
    setTimedToast(data.degraded ? "已生成启发式规则草案，请人工确认" : "AI 已生成规则草案，请人工确认");
  };

  const saveRule = (): void => {
    try {
      const rule = JSON.parse(ruleText) as ParseRule;
      const nextRules = [rule, ...rules.filter((item) => item.id !== rule.id)];
      setRules(nextRules);
      setSelectedRuleId(rule.id);
      localStorage.setItem("rules", JSON.stringify(nextRules));
      setTimedToast("规则已保存");
    } catch {
      setTimedToast("规则 JSON 格式不正确");
    }
  };

  const runParse = (): void => {
    if (!sheets.length) return setTimedToast("请先上传文件");
    const parsed = parseByRule(sheets, selectedRule);
    const nextIssues = validateRows(parsed, existingCodes);
    setRows(parsed.map((row) => ({ ...row, errors: nextIssues.filter((issue) => issue.rowId === row.id).map((issue) => issue.message) })));
    setIssues(nextIssues);
    setTimedToast(`试解析完成：${parsed.length} 行，${nextIssues.length} 个问题`);
  };

  const updateCell = (id: string, field: OrderField, value: string): void => {
    const nextRows = rows.map((row) => row.id === id ? { ...row, [field]: field === "quantity" ? value : value } : row);
    const nextIssues = validateRows(nextRows, existingCodes);
    setRows(nextRows.map((row) => ({ ...row, errors: nextIssues.filter((issue) => issue.rowId === row.id).map((issue) => issue.message) })));
    setIssues(nextIssues);
  };

  const exportExcel = async (): Promise<void> => {
    const ExcelJS = await import("exceljs");
    const book = new ExcelJS.Workbook();
    const sheet = book.addWorksheet("预览数据");
    sheet.columns = [
      { header: "来源", key: "source" },
      ...fields.map((field) => ({ header: field.label, key: field.key })),
      { header: "错误", key: "errors" }
    ];
    rows.forEach(({ errors, source, ...row }) => sheet.addRow({ source, ...row, errors: errors.join(";") }));
    const buffer = await book.xlsx.writeBuffer();
    const url = URL.createObjectURL(new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = "万能导入预览结果.xlsx";
    link.click();
    URL.revokeObjectURL(url);
  };

  const submitOrders = async (): Promise<void> => {
    if (issues.length) return setTimedToast("存在校验错误，请修正后再提交");
    setBusy(true);
    setProgress(60);
    const response = await fetch("/api/orders", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(rows) });
    const data = await response.json();
    const nextHistory = [...rows, ...history];
    setHistory(nextHistory);
    localStorage.setItem("orders", JSON.stringify(nextHistory));
    setBusy(false);
    setProgress(100);
    setTimedToast(`提交成功 ${data.saved ?? rows.length} 条，模式：${data.mode}`);
  };

  return (
    <main>
      <section className="shell">
        <header className="topbar">
          <div>
            <p className="eyebrow">万能导入 V2</p>
            <h1>智能多格式批量下单系统</h1>
          </div>
          <div className="status"><CheckCircle2 size={18} />{toast}</div>
        </header>

        <div className="grid">
          <section className="panel">
            <div className="panel-title"><FileUp size={18} /> 文件导入</div>
            <label className="dropzone">
              <input type="file" accept=".xlsx,.xls,.docx,.pdf" onChange={(event) => event.target.files?.[0] && readFile(event.target.files[0])} />
              <strong>{fileName || "拖拽或点击上传文件"}</strong>
              <span>支持 Excel、Word、PDF；上传后手动选择规则或新建 AI 草案</span>
            </label>
            <div className="progress"><span style={{ width: `${progress}%` }} /></div>
            <div className="sheet-list">{sheets.map((sheet) => <span key={sheet.name}>{sheet.name} · {sheet.rows.length} 行</span>)}</div>
          </section>

          <section className="panel">
            <div className="panel-title"><Wand2 size={18} /> 解析规则</div>
            <select value={selectedRuleId} onChange={(event) => setSelectedRuleId(event.target.value)}>
              {rules.map((rule) => <option key={rule.id} value={rule.id}>{rule.name}</option>)}
            </select>
            <div className="actions">
              <button onClick={generateRule} disabled={busy}><Wand2 size={16} /> AI 生成规则</button>
              <button onClick={() => setRuleText(JSON.stringify({ ...seedRules[0], id: crypto.randomUUID(), name: "新建规则" }, null, 2))}><Plus size={16} /> 新建规则</button>
              <button onClick={saveRule}><Save size={16} /> 保存</button>
              <button onClick={runParse}><Play size={16} /> 试解析</button>
            </div>
            <textarea value={ruleText} onChange={(event) => setRuleText(event.target.value)} spellCheck={false} />
          </section>
        </div>

        <section className="panel wide">
          <div className="panel-title"><AlertCircle size={18} /> 数据预览与校验</div>
          {issues.length > 0 && <div className="error-box">{issues.slice(0, 30).map((issue) => <span key={`${issue.rowId}-${issue.field}`}>第 {issue.rowNumber} 行：{issue.message}</span>)}</div>}
          <div className="table-wrap">
            <table>
              <thead><tr><th>操作</th>{fields.map((field) => <th key={field.key}>{field.label}</th>)}</tr></thead>
              <tbody>
                {visibleRows.map((row) => (
                  <tr key={row.id} className={row.errors.length ? "bad" : ""}>
                    <td><button className="icon" onClick={() => setRows(rows.filter((item) => item.id !== row.id))}><Trash2 size={15} /></button></td>
                    {fields.map((field) => <td key={field.key}><input value={String(row[field.key] ?? "")} onChange={(event) => updateCell(row.id, field.key, event.target.value)} /></td>)}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="actions sticky-actions">
            <button onClick={() => setRows([{ ...rows[0], id: crypto.randomUUID(), externalCode: "", skuCode: "", skuName: "", quantity: "", errors: [] }, ...rows])} disabled={!rows.length}><Plus size={16} /> 新增行</button>
            <button onClick={exportExcel} disabled={!rows.length}><Download size={16} /> 导出 Excel</button>
            <button onClick={submitOrders} disabled={!rows.length || busy}><Database size={16} /> 提交下单</button>
            <span>当前渲染 {visibleRows.length}/{rows.length} 行，超过 300 行分批展示以保证流畅</span>
          </div>
        </section>

        <section className="panel wide">
          <div className="panel-title"><Database size={18} /> 已导入运单</div>
          <input className="search" value={filter} onChange={(event) => setFilter(event.target.value)} placeholder="按外部编码、收件人、门店筛选" />
          <div className="history">
            {filteredHistory.slice(0, 80).map((row) => <div key={row.id}><strong>{row.externalCode || row.storeName || "未命名运单"}</strong><span>{row.receiverName} {row.skuName} × {row.quantity}</span></div>)}
            {!filteredHistory.length && <p className="empty">暂无历史记录</p>}
          </div>
        </section>
      </section>
    </main>
  );
}
